// Junta el formulario (del webhook) + el texto del OCR y llama a la lógica
// de comparación (pega aquí el contenido de nodo-comparacion-ocr.js, adaptado
// para leer un solo item). Ver README para el código completo.

const entrada = $('Webhook (la app dispara)').first().json.body;
const formulario = entrada.formulario || {};
const donacion_id = entrada.donacion_id;

// Texto que devolvió Google Vision (ajusta la ruta según la salida real del nodo):
const textoOCR = $json.textAnnotations?.[0]?.description
  || $json.fullTextAnnotation?.text
  || $json.text
  || '';

const ocr = { texto_completo: textoOCR, monto_detectado: null, fecha_detectada: null, referencia_detectada: null };

// ▼▼▼ PEGA AQUÍ las funciones de nodo-comparacion-ocr.js (CONFIG, normalizarMonto,
// detectarMoneda, aFecha, normalizarRef, extraerDeTexto, validar) ▼▼▼
// ... (idénticas a tu archivo) ...

const validacion = validar(formulario, ocr); // { estado, confianza, checks, motivos }
return [{ json: { donacion_id, ...validacion } }];
